#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic)
# campaign_split_v6_aw2.sh — Autoware traced modes (lttng x3, nsys x3) AFTER
# round 2 of the Isaac sweep. Reason: on 2026-09-06 the first Autoware 3x3 of
# campaign_split_v6 lost lttng #1 to the 900 s docker-exec timeout in
# run_overhead_modes.sh (trace never stopped) and set -e aborted the rest;
# baseline x3 (overhead_aw_20260906_092416) is valid and is reused.
# Waits for DONE-ROUND2 in the campaign log, then runs the traced modes only.
set -u
LOG=$HOME/fish_traces/campaign_split_v6_full.log
until grep -q "DONE-ROUND2" "$LOG" 2>/dev/null; do sleep 60; done
exec >> "$LOG" 2>&1
stamp() { echo "[campaign $(date '+%F %T')] $*"; }
export FISH_APP_CPUS=${FISH_APP_CPUS:-0,2,4,6,8,10} FISH_OBS_CPUS=${FISH_OBS_CPUS:-12-17} FISH_EVENT_COUNT=0
cd "$(dirname "$0")/.."
ip -o link show lo | grep -q MULTICAST || { stamp "ABORT: lo multicast is OFF"; exit 2; }
stamp "Autoware traced modes (lttng x3, nsys x3) after round 2; baseline from overhead_aw_20260906_092416"
IMG=autoware-dev-trt-a1000-fishwait10:latest REPS=3 MODES="lttng nsys" bash scripts/autoware_runs/run_overhead_modes.sh
stamp "Autoware traced rc=$?"
scripts/host_perf_mode.sh status | grep -E "throttle|TCPU"
stamp "DONE-AW2"
